interface Mode { handle(ctx: Device): void }
class OnMode implements Mode { handle(ctx: Device) { console.log('on'); ctx.setMode(new OffMode()); } }
class OffMode implements Mode { handle(ctx: Device) { console.log('off'); ctx.setMode(new OnMode()); } }
class Device { private mode: Mode; constructor() { this.mode = new OffMode(); } press() { this.mode.handle(this); } setMode(m: Mode) { this.mode = m } }

enum Status { New, Paid, Shipped }
class OrderProcessor {
  private status = Status.New
  advance() {
    switch (this.status) {
      case Status.New: this.charge(); this.status = Status.Paid; break
      case Status.Paid: this.ship(); this.status = Status.Shipped; break
      case Status.Shipped: break
    }
  }
  private charge() { /* charge card */ }
  private ship() { /* create shipment */ }
}

